program='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    isolated = set()
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if not any(
                grid[rr][cc] == value
                for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
                if 0 <= rr < h and 0 <= cc < w
            ):
                isolated.add((r, c))

    result = [row[:] for row in grid]
    for r, c in isolated:
        rectangle_colors = []
        for top in (r - 1, r):
            for left in (c - 1, c):
                if 0 <= top < h - 1 and 0 <= left < w - 1:
                    surrounding = [
                        grid[rr][cc]
                        for rr in (top, top + 1)
                        for cc in (left, left + 1)
                        if (rr, cc) != (r, c)
                    ]
                    if len(set(surrounding)) == 1:
                        rectangle_colors.append(surrounding[0])
        object_colors = [value for value in rectangle_colors if value != background]
        if object_colors:
            result[r][c] = Counter(object_colors).most_common(1)[0][0]
        elif rectangle_colors:
            result[r][c] = background
        else:
            neighbors = [
                grid[rr][cc]
                for rr in range(max(0, r - 1), min(h, r + 2))
                for cc in range(max(0, c - 1), min(w, c + 2))
                if (rr, cc) != (r, c) and (rr, cc) not in isolated
            ]
            if neighbors:
                result[r][c] = Counter(neighbors).most_common(1)[0][0]
    return result
'''
